def transform(grid):
    out=[row[:] for row in grid]
    h=len(grid); w=len(grid[0])
    # The one-row pattern is the stamp; its midpoint aligns with each marker.
    motif=[8,0,0,3,0]
    for r,row in enumerate(grid):
        for c,value in enumerate(row):
            if value == 6:
                start=c-len(motif)//2
                for j,color in enumerate(motif):
                    x=start+j
                    if 0 <= x < w:
                        out[r][x]=color
    return out
